package search

import (
	"encoding/json"
	"os"
	"testing"
)

// Feed a REAL row from the live search API through the CLI's decoder.
func TestZZWire(t *testing.T) {
	t.Parallel()
	b, err := os.ReadFile("zz_row.json")
	if err != nil {
		t.Fatal(err)
	}
	var r Result
	if err := json.Unmarshal(b, &r); err != nil {
		t.Fatal(err)
	}
	t.Logf("PROBE real row:  sessionID=%q Matched=%q ResultID=%q DedupID=%q",
		r.Session.SessionID, r.Session.MatchedCheckpointID, r.ResultID(), r.DedupID())

	// Same row with sessionId cleared — what a server-folded legacy session
	// (ENT-1595) looks like once the fold ships, assuming it keeps emitting
	// matchedCheckpointId.
	folded := clearSessionID(t, b)
	var f Result
	if err := json.Unmarshal(folded, &f); err != nil {
		t.Fatal(err)
	}
	t.Logf("PROBE folded:    sessionID=%q Matched=%q ResultID=%q DedupID=%q",
		f.Session.SessionID, f.Session.MatchedCheckpointID, f.ResultID(), f.DedupID())

	// Forward-compat: what if the unmerged fold PR emits `checkpointId` (the
	// name it uses today) instead of `matchedCheckpointId` on folded rows?
	alt := renameField(t, folded, "matchedCheckpointId", "checkpointId")
	var a Result
	if err := json.Unmarshal(alt, &a); err != nil {
		t.Fatal(err)
	}
	t.Logf("PROBE fold w/ checkpointId only: Matched=%q ResultID=%q DedupID=%q",
		a.Session.MatchedCheckpointID, a.ResultID(), a.DedupID())

	// Round-trip: does the field survive marshal/unmarshal (i.e. --json output)?
	out, err := json.Marshal(&r)
	if err != nil {
		t.Fatal(err)
	}
	var back Result
	if err := json.Unmarshal(out, &back); err != nil {
		t.Fatal(err)
	}
	t.Logf("PROBE round-trip: Matched=%q (emits key=%v)",
		back.Session.MatchedCheckpointID, hasKey(t, out, "matchedCheckpointId"))
}

func dataOf(t *testing.T, b []byte) (map[string]json.RawMessage, map[string]json.RawMessage) {
	t.Helper()
	var raw, data map[string]json.RawMessage
	if err := json.Unmarshal(b, &raw); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw["data"], &data); err != nil {
		t.Fatal(err)
	}
	return raw, data
}

func reassemble(t *testing.T, raw, data map[string]json.RawMessage) []byte {
	t.Helper()
	d, err := json.Marshal(data)
	if err != nil {
		t.Fatal(err)
	}
	raw["data"] = d
	out, err := json.Marshal(raw)
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func clearSessionID(t *testing.T, b []byte) []byte {
	t.Helper()
	raw, data := dataOf(t, b)
	data["sessionId"] = json.RawMessage(`""`)
	return reassemble(t, raw, data)
}

func renameField(t *testing.T, b []byte, from, to string) []byte {
	t.Helper()
	raw, data := dataOf(t, b)
	if v, ok := data[from]; ok {
		data[to] = v
		delete(data, from)
	}
	return reassemble(t, raw, data)
}

func hasKey(t *testing.T, b []byte, key string) bool {
	t.Helper()
	_, data := dataOf(t, b)
	_, ok := data[key]
	return ok
}
